"""Generates docs/SAMPLE_IO.md by running the real algorithms (nothing here is hand-typed output).
Run from the project folder:  python docs/make_samples.py"""
import os, sys
sys.path.insert(0, os.path.join(os.path.dirname(__file__), ".."))
from core import (cpu_scheduling as cpu, bankers_algorithm as bank, paging, page_replacement as pr,
                  segmentation as seg, fragmentation as frag, disk_scheduling as disk, multiprogramming as mp)

out = ["# Sample inputs and outputs", "",
       "Generated by `docs/make_samples.py` from the real algorithm code.", ""]

def block(title, inp, res):
    out.extend([f"## {title}", "", "**Input**", "```", inp, "```", "**Output**", "```", res, "```", ""])

# 1 CPU
procs = [cpu.Process("P1", 0, 7, 3), cpu.Process("P2", 2, 4, 1), cpu.Process("P3", 4, 1, 4), cpu.Process("P4", 5, 4, 2)]
for algo, pre, q in (("FCFS", False, None), ("SJF", True, None), ("Round Robin", False, 2)):
    r = cpu.schedule(procs, algo, pre, q)
    lines = ["Gantt: " + " ".join(f"[{s.pid} {s.start}-{s.end}]" for s in r.gantt)]
    lines += [f"{p.pid}: completion={p.completion} turnaround={p.turnaround} waiting={p.waiting}" for p in r.processes]
    lines.append(f"Average waiting = {r.avg_waiting:.2f}, average turnaround = {r.avg_turnaround:.2f}")
    block(f"1. CPU Scheduling - {r.algorithm}", "Process Arrival Burst Priority\nP1 0 7 3\nP2 2 4 1\nP3 4 1 4\nP4 5 4 2", "\n".join(lines))
# 2 Banker
A = [[0,1,0],[2,0,0],[3,0,2],[2,1,1],[0,0,2]]; M = [[7,5,3],[3,2,2],[9,0,2],[2,2,2],[4,3,3]]; V = [3,3,2]
r = bank.check_safety(A, M, V)
block("2. Banker's Algorithm", f"Allocation={A}\nMaximum={M}\nAvailable={V}", f"Need={r.need}\n" + bank.explain(r, V))
# 3 Paging
cfg = paging.PagingConfig(100, 5, 8); tab = paging.build_page_table(cfg, [(0,3),(1,1),(2,None),(3,0)])
lines = []
for a in (117, 5, 345, 250, 800):
    t = paging.translate(cfg, tab, a)
    lines.append(f"address {a}: page={t.page} offset={t.offset} frame={t.frame} physical={t.physical} -> {t.status}")
block("3. Paging", "page size=100, frames=5, pages=8\npage table: 0->3, 1->1, 2->(not in memory), 3->0\naddresses: 117 5 345 250 800", "\n".join(lines))
# 4 Page replacement
refs = [7,0,1,2,0,3,0,4,2,3,0,3,2,1,2,0,1,7,0,1]
lines = []
for r in pr.compare_all(refs, 3):
    lines.append(f"{r.algorithm}: hits={r.hits} faults={r.faults} hit ratio={r.hit_ratio*100:.1f}%")
f = pr.fifo(refs, 3)
lines.append("FIFO frame states: " + " | ".join(f"{s.page}:{[x if x is not None else '-' for x in s.frames]}" + ("" if s.hit else "F") for s in f.steps[:8]) + " ...")
block("4. Page Replacement", "reference string: " + " ".join(map(str, refs)) + "\nframes=3", "\n".join(lines))
# 5 Segmentation
S = [seg.SegmentEntry(0,1400,1000), seg.SegmentEntry(1,6300,400), seg.SegmentEntry(2,4300,400)]
table, _ = seg.build_table(S)
lines = []
for s, o in ((2,53),(1,399),(1,400),(0,1222),(9,1)):
    t = seg.translate(table, s, o); lines.append(f"({s},{o}) -> {t.physical} {t.status}: {t.message}")
block("5. Segmentation", "segments: 0(base1400,limit1000) 1(6300,400) 2(4300,400)\naddresses: (2,53) (1,399) (1,400) (0,1222) (9,1)", "\n".join(lines))
# 6 Fragmentation
B = [100,500,200,300,600]; P = [("P1",212),("P2",417),("P3",112),("P4",426)]
for mode in (frag.FIXED, frag.VARIABLE):
    block(f"6. Fragmentation - First Fit, {mode}", f"blocks={B}\nprocesses={P}", frag.explain(frag.allocate(B, P, "First Fit", mode)))
# 7 Disk
req = [98,183,37,122,14,124,65,67]
lines = [f"{r.algorithm:7s} order={r.service_order} total={r.total_movement}" for r in disk.compare_all(req, 53, 0, 199)]
block("7. Disk Scheduling", f"requests={req}\nhead=53, cylinders 0-199, direction=up, count return jump", "\n".join(lines))
# 8 Multiprogramming
jobs = [mp.Job("A",40,0,4), mp.Job("B",40,0,4), mp.Job("C",40,0,2)]
r = mp.simulate(jobs, 100, 0, 2)
lines = [f"t={s.time}: {s.event} | in memory={[p.pid for p in s.loaded]} waiting={s.waiting}" for s in r.snapshots]
lines.append(f"CPU util={r.cpu_utilization*100:.0f}%  memory util={r.memory_utilization*100:.0f}%  total time={r.total_time}")
block("8. Multiprogramming", "memory=100, quantum=2\nA mem40 arr0 burst4\nB mem40 arr0 burst4\nC mem40 arr0 burst2", "\n".join(lines))

path = os.path.join(os.path.dirname(__file__), "SAMPLE_IO.md")
open(path, "w", encoding="utf-8").write("\n".join(out))
print("wrote", path)
